(1, 'User Mail Send', 'user_mail', 'User', 'global/images/Uxp3vfYFFi4GuO95lyZn.jpg', 'Sample Email', '[[subject]] for [[full_name]]', 'Hi [[full_name]],', 'Thanks for joining us  [[site_title]]<br />\r\n<br />\r\n[[message]]<br />\r\n<br />\r\n<br />\r\nFind out more about in - [[site_url]]', 'Login Your Account', NULL, 1, 'Regards,<br />\r\n[[site_title]]', 0, 'What is [[site_title]]', '[[site_title]]', '[\"[[full_name]]\",\"[[site_url]]\",\"[[site_title]]\",\"[[subject]]\",\"[[message]]\"]', 0, NULL, '2022-12-09 18:37:23'),
(2, 'Subscriber Mail Send', 'subscriber_mail', 'Subscriber', NULL, 'Welcome to [[site_title]]', '[[subject]] for [[full_name]]', 'Hi [[full_name]],', 'Thanks for joining our platform! ---  [[site_title]]<br />\r\n<br />\r\n[[message]]<br />\r\n<br />\r\nAs a member of our platform, you can mange your account, buy or sell cryptocurrency, invest and earn profits.<br />\r\n<br />\r\nFind out more about in - [[site_url]]', 'Login Your Account', NULL, 1, 'Thanks for joining our platform! ---  [[site_title]]<br />\r\n<br />\r\n[[message]]<br />\r\n<br />\r\nAs a member of our platform, you can mange your account, buy or sell cryptocurrency, invest and earn profits.<br />\r\n<br />\r\nFind out more about in - [[site_url]]', 1, 'What is [[site_title]]', '[[site_title]]', '[\"[[site_url]]\",\"[[site_title]]\",\"[[subject]]\",\"[[message]]\"]', 0, NULL, '2022-12-09 18:37:30'),
(3, 'Email Verification', 'email_verification', 'User', NULL, 'Verify Email Address', 'Verify Email Address', 'Hi [[full_name]],', 'Hello!<br />\r\nPlease click the button below to verify your email address.', 'Verify Email Address', '[[token]]', 1, 'Regards,<br />\r\n[[site_title]]', 1, 'Verify Email Address', 'If you\'re having trouble clicking the \"Verify Email Address\" button, copy and paste the URL below into your web browser:[[token]]', '[\"[[token]]\",\"[[full_name]]\",\"[[site_title]]\",\"[[site_url]]\"]', 1, NULL, '2023-02-16 03:06:43'),
(4, 'Forget Password', 'user_password_change', 'User', NULL, 'User Password Change', 'User Forget Password', 'Hi user,', 'Please click the button below to Change the Password.', 'Reset Password', '[[token]]', 1, 'Regards,<br />\r\n[[site_title]]', 0, 'User Password Change', '[[token]]', '[\"[[token]]\",\"[[site_title]]\",\"[[site_url]]\"]', 1, NULL, '2023-02-16 03:07:29'),
(6, 'User Account Disabled', 'user_account_disabled', 'User', NULL, 'Sorry to say that', 'Your Account is Disabled', 'Hi [[full_name]],', 'I hope this message finds you well. We are reaching out to inform you that your account with [[site_title]] has been deactivated due to inactivity. It appears that you have not logged in for the past [[inactive_days]] days.<br />\r\n<br />\r\nAccount security is a top priority for us, and as part of our regular security measures, inactive accounts are deactivated to ensure the safety of your information and our systems. If you believe this deactivation is in error or if you would like to reactivate your account, please contact our support team as soon as possible.<br />\r\n<br />\r\nIf you wish to reactivate your account, our support team will guide you through the necessary steps to regain access. Please note that for security reasons, we may require additional verification to ensure the account\'s rightful owner is making the request.<br />\r\n<br />\r\nWe value your membership with [[site_title]] and encourage you to stay engaged with our services. If you have any concerns or questions regarding this deactivation, feel free to reach out to our support team.<br />\r\n<br />\r\nThank you for your understanding and cooperation.', 'Contact Us', 'https://hyiprio.tdevs.co/contact', 0, 'Regards,<br />\r\n[[site_title]]', 0, 'User Account Disabled', '[[full_name]]', '[\"[[full_name]]\",\"[[site_title]]\",\"[[site_url]]\"]', 1, NULL, '2023-12-25 03:43:10'),
(7, 'Manual Deposit request', 'manual_deposit_request', 'Admin', NULL, 'Manual Deposit request', 'Got a request for Manual Deposit', 'Hi Admin,', 'The manual deposit request details:<br />\r\n[[txn]]<br />\r\n[[gateway_name]]<br />\r\n[[deposit_amount]]', 'Review The requests', NULL, 1, 'Regards,<br />\r\n[[site_title]]', 0, 'Manual Deposit request', '[[site_title]]', '[\"[[full_name]]\",\"[[txn]]\",\"[[gateway_name]]\",\"[[deposit_amount]]\",\"[[site_title]]\",\"[[site_url]]\"]', 0, NULL, '2023-02-03 20:27:15'),
