(12, 'Experience Section\r\n', 'experiencesection', '{\"title_small\":\"Tailored experiences\",\"title_big\":\"Our Powerful Solutions\",\"description\":\"Fund transfer involves moving money from one account to another, whether it\'s within the same financial institution or between different banks. This process can be initiated through various channels, including online banking, mobile banking apps, ATM transactions, wire transfers, or in-person visits to bank branches.\",\"left_img\":\"global\\/images\\/ooVxFs7wZj2KVGptmPpR.png\",\"left_shape_img\":\"global\\/images\\/04C4SrC8P2fi2eXDpVYA.png\",\"right_img\":\"global\\/images\\/x1AJhPJgfB30mkoLjiG7.png\"}', 1, '2022-10-22 13:54:48', '2024-06-10 06:27:30', 7, 'en'),
